export function captureProcessTreeSnapshot(child: ChildProcess, options?: ProcessTreeTerminatorOptions): ProcessTreeSnapshot | undefined;

export function captureProcessGroupSnapshot(processGroupId: number, options?: ProcessTreeTerminatorOptions): ProcessTreeSnapshot | undefined;

export function captureExitedRootDescendantsSnapshot(rootPid: number, options?: ProcessTreeTerminatorOptions): ProcessTreeSnapshot | undefined;

import type { ChildProcess } from "node:child_process";

