export function captureProcessTreeSnapshot(
  child: ChildProcess,
  options: ProcessTreeTerminatorOptions = {},
): ProcessTreeSnapshot | undefined {
  const rootPid = child.pid;
  if (rootPid == null) {
    return undefined;
  }
  const table = queryIdentities(options);
  const root = table.find((identity) => identity.pid === rootPid);
  if (!root) {
    return undefined;
  }
  const candidates = [root, ...descendantsOf(rootPid, table)];
  if (process.platform !== "win32" && root.processGroupId === rootPid) {
    candidates.push(
      ...table.filter((identity) => identity.processGroupId === rootPid),
