  }
  const byPid = new Map(
    candidates.map((identity) => [identity.pid, identity]),
  );
  const identities = refineIdentities([...byPid.values()]);
  if (!identities.some((identity) => identity.pid === rootPid)) {
    return undefined;
  }
  return {
    rootPid,
    descendantPids: identities
      .filter((identity) => identity.pid !== rootPid)
      .map((identity) => identity.pid),
    identities,
  };
}

