          }
          options.log?.warn(
            options.traceId,
            "查询 Windows runtime 进程表失败（异步）:",
            error ?? stderr,
          );
          resolve([]);
          return;
        }
        let identities: ProcessIdentity[];
        try {
          identities = parseWindowsProcessIdentities(stdout);
        } catch (parseError) {
          reject(parseError);
          return;
        }
        if (identities.length === 0) {
          options.log?.warn(
            options.traceId,
            "PowerShell 未返回可解析的 Windows runtime 进程表",
          );
        } else {
          windowsCimCapability = "cim";
        }
        resolve(identities);
      },
    );
  }).finally(() => {
    if (windowsProcessListFlight?.promise === request) {
      windowsProcessListFlight = undefined;
    }
  });
  windowsProcessListFlight = { promise: request, startedAtMs };
  return await awaitWindowsProcessListWithinDeadline(
    request,
